select public.provision_bulk_user('DPS','{"employee_id":"ef200000-0000-4000-8000-000000000001","full_name":"Wrong typed name","email":"staff.profile.qa@example.invalid","npp":"99381","is_active":false}',array['tester']);
select pg_temp.check_true((select employee_id='ef200000-0000-4000-8000-000000000001' and is_active from public.profiles where id='ef100000-0000-4000-8000-000000000002'));
select set_config('request.jwt.claim.sub','ef100000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select pg_temp.check_true(public.initial_password_change_required());
select pg_temp.check_true(not private.actor_enabled());
select pg_temp.check_true(not private.branch_access('DPS'));
do $$begin begin delete from private.bulk_initial_passwords where profile_id=auth.uid();raise exception 'Expected private marker denial';exception when insufficient_privilege then null;end;end $$;
do $$begin begin perform public.provision_bulk_user('DPS','{}',array['super_admin']);raise exception 'Expected bulk RBAC denial';exception when insufficient_privilege then null;end;end $$;
reset role;
update auth.users set encrypted_password='[CONTOH] Auth-managed password change simulation' where id='ef100000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.check_true(not public.initial_password_change_required());
select pg_temp.check_true(private.actor_enabled());
select pg_temp.check_true(private.branch_access('DPS'));
select set_config('request.jwt.claim.sub','ef100000-0000-4000-8000-000000000001',true);
do $$begin begin perform public.provision_bulk_user('DPS','{}',array['tester']);raise exception 'Expected MFA denial';exception when insufficient_privilege then null;end;end $$;
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
do $$begin begin perform public.provision_bulk_user('DPS','{"employee_id":"ef200000-0000-4000-8000-000000000001","full_name":"Wrong","email":"staff.profile.qa@example.invalid","npp":"99381","is_active":false}',array['tester']);raise exception 'Expected duplicate rejection';exception when check_violation then null;end;end $$;
reset role;
select pass('Bulk creates profile and roles atomically; mandatory initial password change enforced by RLS and Auth trigger; MFA, RBAC and duplicates protected');
select * from finish();rollback;
